"""Offline tests of round 5's harness measures (relay_proof: takeover_measures, claim_answers, contract_side_measures,
contract_reads, question_duplicates). Usage: python3 -I test_round5.py"""
import json, os, sys, tempfile, unittest

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import relay_proof as rp  # noqa: E402


def features():
    """relay_proof_features.json (the benchmark copy). It is generated by devbench/features.py from DevBench and not
    shipped in the repo, so the tests that need it skip there."""
    path = os.path.join(HERE, 'relay_proof_features.json')
    if not os.path.exists(path):
        raise unittest.SkipTest(f'{path} not found: generate it with python3 -I devbench/features.py')
    return json.load(open(path))


class FakeOrch:
    def __init__(self, seen):
        self.stall_seen = seen


class FakeProc:
    def __init__(self, name):
        self.name = name


def tool_result(ans):
    return json.dumps(dict(type='user', message=dict(content=[dict(type='tool_result', tool_use_id='x',
                                                                     content=[dict(type='text', text=json.dumps(ans))])])))


class Takeover(unittest.TestCase):
    def test_task_and_path_takeovers(self):
        t0 = 1000.0
        rows = [
            dict(_timestamp=int(130e6) + int(t0 * 1e6), agent='agent-1', kind='HANDOFF', key='name:task 06 word_freq',
                 text='stalled: taken over by agent-2', to='agent-2'),
            dict(_timestamp=int(130e6) + int(t0 * 1e6), agent='agent-1', kind='HANDOFF', key='path:src/word_freq.py',
                 text='stalled: taken over by agent-2', to='agent-2'),
            dict(_timestamp=int(140e6) + int(t0 * 1e6), agent='agent-1', kind='HANDOFF', key='path:REGISTRY.md',
                 text='stalled: taken over by agent-2', to='agent-2'),
            dict(_timestamp=int(50e6) + int(t0 * 1e6), agent='agent-1', kind='HANDOFF', key='name:task 01 slugify',
                 text='to agent-2', to='agent-2'),  # an ordinary handoff is not a takeover
        ]
        seen = {'name:task 06 word_freq': dict(first_seen=t0 + 121, first_seen_s=121, last_activity_ts=int((t0 + 60) * 1e6)),
                'path:REGISTRY.md': dict(first_seen=t0 + 131, first_seen_s=131, kind='path')}
        timeline = {'agent-1': dict(edits=[dict(ts=t0 + 55, path='src/word_freq.py', applied=True)]),
                    'agent-2': dict(edits=[dict(ts=t0 + 135, path='src/word_freq.py', applied=True)])}
        cwd = tempfile.mkdtemp()
        with open(os.path.join(cwd, '.log-agent-2.jsonl'), 'w') as fh:
            fh.write(tool_result(dict(held=True, resource='task 06 word_freq', key='name:task 06 word_freq',
                                      taken_over_from='agent-1', stall=dict(idle_s=69, last_activity_ts=int((t0 + 61) * 1e6)))) + '\n')
            fh.write(tool_result(dict(held=False, resource='task 07 roman', reason='not_stalled', stall=dict(idle_s=5))) + '\n')
        open(os.path.join(cwd, '.log-agent-1.jsonl'), 'w').close()
        res = dict(score=dict(per_task={f't{i}': True for i in range(12)}), duplicated=['src/word_freq.py'])
        m = rp.takeover_measures(rows, FakeOrch(seen), timeline, [FakeProc('agent-1'), FakeProc('agent-2')], cwd, res, t0)
        self.assertEqual((m['n'], m['n_tasks'], m['n_paths']), (2, 1, 1))
        task = m['takeovers'][0]
        self.assertEqual(task['files'], ['src/word_freq.py'])
        self.assertEqual(task['after_stalled_reading_s'], 9.0)
        self.assertEqual(task['after_holder_last_activity_s'], 69.0)  # from the takeover answer, not the poll
        self.assertEqual(task['giver_edits_after'], 0)
        self.assertEqual(m['takeovers'][1]['kind'], 'path')
        self.assertEqual(m['duplicated_by_takeover'], ['src/word_freq.py'])
        self.assertEqual(m['duplicated_other'], [])
        self.assertEqual(len(m['refused']), 1)
        self.assertEqual(m['tasks_completed'], 12)


class Contracts(unittest.TestCase):
    def setUp(self):
        self.c = features()['readtime']['contracts']

    def transcript(self, reads):
        path = os.path.join(tempfile.mkdtemp(), 't.jsonl')
        with open(path, 'w') as fh:
            for i, ans in enumerate(reads):
                fh.write(json.dumps(dict(type='assistant', message=dict(content=[dict(type='tool_use', id=f'c{i}',
                                                                                       name='mcp__ctrlb__contracts', input={})]))) + '\n')
                fh.write(json.dumps(dict(type='user', message=dict(content=[dict(type='tool_result', tool_use_id=f'c{i}',
                                                                                  content=json.dumps(ans))]))) + '\n')
        return path

    def test_reader_measures(self):
        t0 = 1000.0
        con = lambda text, cs, csr: dict(name='readtime result', paths=['path:readtime/result.py'], text=text,
                                         changed_since=cs, changed_since_read=csr)
        path = self.transcript([dict(read_at=int((t0 + 50) * 1e6), contracts=[con('Result(seconds, wpm)', [], True)]),
                                dict(read_at=int((t0 + 100) * 1e6), contracts=[con('Revised: Result(words, images, wpm)', [], True)])])
        orig = rp.transcript_path
        rp.transcript_path = lambda sid: path
        try:
            change = dict(at=t0 + 90, provider='agent-1', dependent='agent-2', by='provider first contract')
            m = rp.contract_side_measures(dict(contracts_mode='reader'), self.c, change, [], {'agent-2': dict(session_id='s')},
                                          {'agent-2': dict(edits=[dict(ts=t0 + 110, path='readtime/utils.py', applied=True)])}, t0)
        finally:
            rp.transcript_path = orig
        self.assertTrue(m['triggered'])
        self.assertEqual(m['dependent_contracts_reads'], 2)
        self.assertEqual(m['next_read_s'], 100.0)
        self.assertTrue(m['changed_since_read'])
        self.assertFalse(m['changed_since_nonempty'])
        self.assertTrue(m['next_read_has_new_sig'])
        self.assertTrue(m['dependent_edited_after_read'])

    def test_provider_republish_is_the_reference(self):
        t0 = 1000.0
        crow = [dict(_timestamp=int((t0 + 95) * 1e6), agent='agent-1', kind='BRIEF', key='contract:readtime result'),
                dict(_timestamp=int((t0 + 80) * 1e6), agent='agent-1', kind='BRIEF', key='contract:readtime result')]
        change = dict(at=t0 + 90, provider='agent-1', dependent='agent-2')
        m = rp.contract_side_measures(dict(contracts_mode='provider'), self.c, change, crow, {'agent-2': {}},
                                      {'agent-2': dict(edits=[])}, t0)
        self.assertTrue(m['provider_republished'])
        self.assertEqual(m['ref_s'], 95.0)
        self.assertEqual(m['dependent_reads_after'], 0)

    def test_untriggered(self):
        m = rp.contract_side_measures(dict(contracts_mode='reader'), self.c, dict(by=None, at=None), [], {}, {}, 0)
        self.assertEqual(m, dict(mode='reader', triggered=False))

    def test_revision_text(self):
        import re
        rv = self.c['revise']
        self.assertEqual(re.sub(rv['pattern'], rv['new_sig'], 'class Result(seconds, wpm) in readtime/result.py'),
                         'class Result(words, images, wpm) in readtime/result.py')


class Questions(unittest.TestCase):
    def test_same_fact_two_agents(self):
        feat = features()['readtime']
        ask = {'task 02 utils': ['the default reading speed (words per minute) used when none is given'],
               'task 03 api': ['the default reading speed (words per minute) used when none is given']}
        qs = [dict(agent='agent-1', text='What is the default WPM when none is given?', ts=1),
              dict(agent='agent-2', text='Which reading speed should read_time use by default?', ts=2),
              dict(agent='agent-2', text='Should api.py re-export Result?', ts=3)]
        d = rp.question_duplicates(qs, rp.ask_entries(feat, ask))
        self.assertEqual((d['duplicates'], d['by_two_agents'], d['unmatched']), (1, 1, 1))


if __name__ == '__main__':
    unittest.main()
